*
 * GET /admin/orders/count.json
 *
 * Examples:
 *
 *      insales.countOrder({
 *        token: '1234567890',
 *        url: 'shop-test.myinsales.ru'
 *      }).then(response => {
 *        console.info(response.data);
 *      }).catch(err => {
 *        console.error(err);
 *      });
 * Output:
 *
 *      {
 *        "count": 6
 *      }
 * @param {Object} options
 * @param {string} options.token Required, access token for shop
 * @param {string} options.url Required, shop url
 * @param {string|string[]} [options.fulfillment_status] Order status or array of statuses
 * @param {number|number[]} [options.delivery_variant] Delivery variant id or array of ids
 * @param {number|number[]} [options.payment_gateway_id] Payment gateway id or array of ids
 * @param {Number|String} id Required, app id
 * @returns {Promise}

